export default function dropcontactLeadPlans({ data, error, success, status, raw, count, campaignId }) {
  if (error !== false || success !== true || status !== 'succeeded') throw new Error('Dropcontact enrichment is not complete after the source wait; do not submit the batch again without checking its request ID');
  if (!Array.isArray(data) || data.length !== count) throw new Error('Dropcontact did not return the complete contact batch');
  if (raw !== null && raw !== undefined && (!Array.isArray(raw.data) || raw.data.length !== count || raw.data.some(record => !record || typeof record !== 'object' || Array.isArray(record)))) throw new Error('Dropcontact returned an invalid or incomplete raw contact batch');
  if (typeof campaignId !== 'string' || !campaignId.trim()) throw new Error('Configure the Lemlist campaign ID');
  const campaignPath = encodeURIComponent(campaignId);
  const plans = data.map((record, index) => {
    if (!record || typeof record !== 'object' || Array.isArray(record) || !Array.isArray(record.email) || !record.email.length || typeof record.email[0]?.email !== 'string' || !record.email[0].email.trim()) throw new Error('Contact ' + (index + 1) + ' has no first enriched email; no leads have been created by this step');
    const email = record.email[0].email;
    const body = {};
    for (const [target, source] of [['firstName', 'first_name'], ['lastName', 'last_name'], ['companyName', 'company']]) {
      if (record[source] === undefined) continue;
      if (record[source] !== null && typeof record[source] !== 'string') throw new Error('Invalid enriched field ' + source + ' at contact ' + (index + 1));
      body[target] = record[source];
    }
    return { email, emailPath: encodeURIComponent(email), campaignPath, endpoint: '/campaigns/' + campaignPath + '/leads/' + encodeURIComponent(email), body };
  });
  return { plans, enriched: data, count };
}

