export default function sheetLemlistResult({ state, enriched, submission, expectedCount }) {
  if (!state || !Array.isArray(state.leads) || state.leads.length !== expectedCount || state.index !== expectedCount) throw new Error('The complete sheet contact batch has not been confirmed in Lemlist');
  if (expectedCount === 0) return { leads: [], enriched: [], submission: null, count: 0 };
  if (!Array.isArray(enriched) || enriched.length !== expectedCount || !submission || typeof submission !== 'object') throw new Error('Missing the complete enrichment/submission result');
  return { leads: state.leads, enriched, submission, count: state.leads.length };
}
